/*
   Teensy 4.x HYBRID: AUDIO PLAYBACK + REAL-TIME DRUM SYNTH
   - Playback: AudioPlayMemory for reference samples
   - Synthesis: FM attack + Karplus–Strong body + Noise transient
   - Real-time control: Flex sensor controls pitch, FSR controls sustain/damping, Piezo velocity controls amplitude
*/

#include <Arduino.h>
#include <Audio.h>
#include <FreeRTOS.h>
#include <task.h>
#include <math.h>
#include <Wire.h>
#include <SPI.h>

#include "drum_raw.h" // generated by create.py

#define analogReadFast(pin) analogRead(pin)

// ------------------- PINS -------------------
#define PIEZO_CENTER_PIN A2
#define FLEX_PIN A1
#define FSR_PIN A0

// ------------------- CONFIG -------------------
#define ANALOG_RESOLUTION_BITS 10
#define ADC_MAX 1024

#define PIEZO_THRESHOLD 250
#define PIEZO_DEBOUNCE_MS 2

#define FLEX_MIN 250
#define FLEX_MAX 3800
#define FLEX_SMOOTH_ALPHA 0.24f
#define FLEX_EXPONENT 1.85f

// =============== AUDIO OBJECTS ===============
// Playback
AudioPlayMemory       playMem;

// Synthesis: FM attack
AudioSynthWaveform fmMod;
AudioSynthWaveformModulated fmCar;
AudioEffectEnvelope fmEnv;

// Synthesis: Karplus–Strong body
AudioSynthKarplusStrong ks;
AudioFilterStateVariable ksFilter;

// Synthesis: Noise transient
AudioSynthNoiseWhite noise1;
AudioEffectEnvelope noiseEnv;
AudioFilterStateVariable noiseFilter;

// Mixer & output (4 channels: playback, KS, noise, FM)
AudioMixer4 mixer;
AudioOutputI2S i2s1;
AudioControlSGTL5000 audioShield;

// Patch cords: Playback
AudioConnection patchCordPlayL(playMem, 0, mixer, 0);

// Patch cords: FM
AudioConnection patchCord1(fmMod, 0, fmCar, 0);
AudioConnection patchCord2(fmCar, 0, fmEnv, 0);
AudioConnection patchCord3(fmEnv, 0, mixer, 3);

// Patch cords: KS
AudioConnection patchCordKS(ks, 0, ksFilter, 0);
AudioConnection patchCordKSOut(ksFilter, 0, mixer, 1);

// Patch cords: Noise
AudioConnection patchCord5(noise1, 0, noiseFilter, 0);
AudioConnection patchCord6(noiseFilter, 0, noiseEnv, 0);
AudioConnection patchCord6b(noiseEnv, 0, mixer, 2);

// Patch cords: Output
AudioConnection patchCord7(mixer, 0, i2s1, 0);
AudioConnection patchCord8(mixer, 0, i2s1, 1);

// =============== GLOBAL STATE ===============
volatile uint16_t piezoCenterPeak = 0;
volatile uint32_t lastHitMs = 0;
volatile float smoothedFlex = 0.0f;
volatile bool inPeakState = false; // peak-tracking for ISR

// Synth tuning constants (from analyze.py: precisely matched to original audio)
static constexpr float S_MIN_FREQ = 47.5f;        // Hz (analyzed: 47.5 Hz min)
static constexpr float S_MAX_FREQ = 189.1f;       // Hz (analyzed: 189.1 Hz max)
static constexpr int S_FM_DROP_MS = 9;            // ms (analyzed: 9.3 ms pitch drop)
static constexpr int S_KS_SUSTAIN_MS = 30;        // ms (analyzed: 30 ms sustain - VERY SHORT)
static constexpr float S_FM_INDEX_SCALE = 12.10f; // FM strength (analyzed: 12.1 - strong attack)
static constexpr float S_NOISE_LEVEL_SCALE = 0.91f; // noise level (analyzed: 0.91)

float minFreq = S_MIN_FREQ;
float maxFreq = S_MAX_FREQ;

// Mixer/KS fade state
float gMixerKSGainDefault = 1.6f;
bool gKsFadeActive = false;
uint32_t gKsFadeStartMs = 0;
const uint32_t G_KS_FADE_MS = 40;

// Pitch envelope
struct PitchEnvState {
  bool active;
  float startFreq;
  float endFreq;
  uint32_t startMs;
  uint32_t durMs;
};
PitchEnvState gPitchEnv = {false, 0, 0, 0, 0};

volatile uint32_t ksNoteOffMs = 0;

// =============== HELPERS ===============
static inline float clampf(float v, float lo, float hi) {
  return (v < lo) ? lo : (v > hi) ? hi : v;
}

static inline int clampi(int v, int lo, int hi) {
  return (v < lo) ? lo : (v > hi) ? hi : v;
}

void triggerDrum(uint16_t peakC, float flex, uint16_t fsr);

float velocityNorm(uint16_t peak) {
  if (peak <= PIEZO_THRESHOLD) return 0.0f;
  float n = (float)(peak - PIEZO_THRESHOLD) / (float)(ADC_MAX - PIEZO_THRESHOLD);
  return clampf(n, 0.0f, 1.0f);
}

float fmIndexFromVelocity(float velNorm) {
  float base = 5.0f + velNorm * 25.0f;
  return base;
}

float noiseAmpFromVelocity(float velNorm) {
  float base = 0.2f + velNorm * 0.5f;
  return clampf(base, 0.0f, 1.0f);
}

void setKSDamping(uint16_t fsr, float velNorm) {
  float fsrN = (float)fsr / 1024.0f;
  // Analyzed KS filter: cutoff ~172 Hz base, resonance Q ~0.5 (warm, non-metallic)
  // This creates a percussive drum body with minimal ringing
  float baseCutoff = 172.0f;  // analyzed base from spectral centroid
  float brightness = velNorm * 100.0f;  // gentle velocity brightness (not aggressive)
  float finalCutoff = baseCutoff + brightness - fsrN * 80.0f;  // FSR darkens
  finalCutoff = constrain(finalCutoff, 100.0f, 400.0f);  // narrow range to keep warm
  ksFilter.frequency(finalCutoff);

  // Low resonance Q to match analyzed warmth and avoid metallic character
  float q = 0.5f + fsrN * 0.3f;  // stays very low (0.5..0.8) - warm and punchy
  q = clampf(q, 0.5f, 0.8f);
  ksFilter.resonance(q);
}

void startPitchEnv(float startFreq, float endFreq, uint32_t durMs) {
  gPitchEnv.active = true;
  gPitchEnv.startFreq = startFreq;
  gPitchEnv.endFreq = endFreq;
  gPitchEnv.startMs = millis();
  gPitchEnv.durMs = durMs;
  fmCar.frequency(startFreq);
}

void updatePitchEnv() {
  if (!gPitchEnv.active) return;
  uint32_t now = millis();
  uint32_t elapsed = now - gPitchEnv.startMs;
  if (elapsed >= gPitchEnv.durMs) {
    fmCar.frequency(gPitchEnv.endFreq);
    gPitchEnv.active = false;
    return;
  }
  float t = (float)elapsed / (float)gPitchEnv.durMs;
  float expTerm = expf(-3.0f * t);
  float f = gPitchEnv.endFreq + (gPitchEnv.startFreq - gPitchEnv.endFreq) * expTerm;
  fmCar.frequency(f);
}

// =============== ISR: SENSOR INPUT ===============
void piezoISR() {
  uint16_t c = analogReadFast(PIEZO_CENTER_PIN);

  if (c > piezoCenterPeak)
    piezoCenterPeak = c;

  uint32_t now = millis();
  bool aboveThreshold = (c > PIEZO_THRESHOLD);

  if (aboveThreshold && !inPeakState && (now - lastHitMs > PIEZO_DEBOUNCE_MS)) {
    inPeakState = true;
    lastHitMs = now;

    uint16_t peakC;
    float flexLocal;
    noInterrupts();
    peakC = piezoCenterPeak;
    piezoCenterPeak = 0;
    flexLocal = smoothedFlex;
    interrupts();

    uint16_t fsr = analogReadFast(FSR_PIN);
    Serial.print("Hit! C:");
    Serial.print(peakC);
    Serial.print(" Flex:");
    Serial.print(flexLocal, 2);
    Serial.print(" FSR:");
    Serial.print(fsr);
    Serial.println();
    triggerDrum(peakC, flexLocal, fsr);
  } else if (!aboveThreshold) {
    inPeakState = false;
  }

  // Flex smoothing
  float flexRaw = analogReadFast(FLEX_PIN);
  smoothedFlex += FLEX_SMOOTH_ALPHA * (flexRaw - smoothedFlex);
}

// =============== TRIGGER DRUM (SYNTH) ===============
void triggerDrum(uint16_t peakC, float flex, uint16_t fsr) {
  uint16_t peak = peakC;
  if (peak < PIEZO_THRESHOLD) return;

  float velN = velocityNorm(peak);

  // Flex → pitch mapping
  float clamped = constrain(flex, FLEX_MIN, FLEX_MAX);
  float norm = (clamped - FLEX_MIN) / (FLEX_MAX - FLEX_MIN);
  float curveExp = 0.65f;
  float curved = powf(norm, curveExp);
  float noteFreq = minFreq + curved * (maxFreq - minFreq);
  Serial.print(" NoteFreq:");
  Serial.println(noteFreq);

  // FSR state
  float fsrN = (float)fsr / (float)ADC_MAX;

  // -------- KS BODY --------
  ks.noteOff(1.0f);
  setKSDamping(fsr, velN);

  float ksVel = 0.5f + velN * 0.5f;
  mixer.gain(1, gMixerKSGainDefault);
  gKsFadeActive = false;
  ks.noteOn(noteFreq, ksVel);

  // Sustain scheduling
  const float FSR_CUTOFF_IMMEDIATE = 0.25f;
  uint32_t sustainMs = (fsrN >= FSR_CUTOFF_IMMEDIATE) ? 50 : (uint32_t)S_KS_SUSTAIN_MS;
  ksNoteOffMs = millis() + sustainMs;

  // -------- FM ATTACK --------
  fmEnv.noteOff();
  float baseFmFreq = noteFreq * 1.2f;
  float fmIndex = fmIndexFromVelocity(velN);

  fmMod.begin(WAVEFORM_SINE);
  fmCar.begin(WAVEFORM_SINE);
  fmMod.frequency(baseFmFreq * 2.0f);
  fmMod.amplitude(fmIndex * S_FM_INDEX_SCALE);

  // FM pitch attack: analyzed to rise quickly, drop very fast (9ms)
  float dropAmt = 1.0f + velN * 1.5f;  // more modest rise (1..2.5x)
  float startF = baseFmFreq * dropAmt;
  uint32_t envDur = (uint32_t)S_FM_DROP_MS;  // very fast drop (9 ms)
  startPitchEnv(startF, baseFmFreq, envDur);

  fmEnv.attack(1);
  fmEnv.decay(8);
  fmEnv.sustain(0);
  fmEnv.release((int)max(10.0f, 80.0f * (1.0f - fsrN)));
  fmEnv.noteOn();

  // -------- NOISE TRANSIENT --------
  noiseEnv.noteOff();
  float nAmp = noiseAmpFromVelocity(velN);
  noise1.amplitude(nAmp * S_NOISE_LEVEL_SCALE);

  // Analyzed: attack 1.5ms, short transient burst with minimal decay
  noiseEnv.attack(1);
  noiseEnv.decay(8);
  noiseEnv.sustain(0);
  noiseEnv.release((int)max(8.0f, 60.0f * (1.0f - fsrN)));

  // Per-hit noise cutoff: analyzed at 1600 Hz for warm transient
  float noiseCut = 1600.0f;  // fixed darker cutoff (not velocity-dependent)
  noiseFilter.frequency(noiseCut);
  noiseEnv.noteOn();
}

// =============== SETUP ===============
void setup() {
  Serial.begin(115200);
  while (!Serial) { delay(10); }
  Serial.println("Hybrid Playback + Synth Online");

  // Pins
  pinMode(PIEZO_CENTER_PIN, INPUT);
  pinMode(FLEX_PIN, INPUT);
  pinMode(FSR_PIN, INPUT);

  // Audio
  AudioMemory(80); // increased for synth + playback
  audioShield.enable();
  audioShield.volume(0.8f);

  delay(50);

  // Mixer gains based on analysis: percussive drum (short, punchy, not sustained)
  mixer.gain(0, 0.6f);  // playback (reference)
  mixer.gain(1, 1.0f);  // KS body (moderate - analyzed as short decay)
  mixer.gain(2, 0.9f);  // noise transient (analyzed: 0.91 level)
  mixer.gain(3, 0.8f);  // FM attack (analyzed: 12.1 index = strong)

  analogReadResolution(ANALOG_RESOLUTION_BITS);
  analogReadAveraging(1);
  smoothedFlex = analogReadFast(FLEX_PIN);

  // Noise filter: tuned for talking drum character (dark, punchy transient)
  noiseFilter.frequency(1600.0f);  // darker noise (not bright metallic hiss)
  noiseFilter.resonance(0.4f);     // minimal resonance in noise

  Serial.println("Ready. Hit the piezo or play drum_raw sample.");
}

// =============== LOOP ===============
void loop() {
  delay(5);

  // Update pitch envelope
  updatePitchEnv();

  // FSR damping
  uint16_t fsr = analogReadFast(FSR_PIN);
  float fsrN = (float)fsr / 1024.0f;
  float q = 1.5f - fsrN * 1.3f;
  q = clampf(q, 0.2f, 1.5f);
  ksFilter.resonance(q);

  // ISR (sensor polling)
  piezoISR();

  // KS note-off + fade
  if (ksNoteOffMs != 0 && millis() >= ksNoteOffMs) {
    gKsFadeActive = true;
    gKsFadeStartMs = millis();
    ksNoteOffMs = 0;
  }

  if (gKsFadeActive) {
    uint32_t e = millis() - gKsFadeStartMs;
    if (e < G_KS_FADE_MS) {
      float t = (float)e / (float)G_KS_FADE_MS;
      float newGain = gMixerKSGainDefault * (1.0f - t);
      mixer.gain(1, newGain);
    } else {
      mixer.gain(1, 0.0f);
      ks.noteOff(1.0f);
      gKsFadeActive = false;
    }
  }

  // Optional: auto-replay drum_raw sample if you want
  // (commented out — uncomment to enable looping playback)
  /*
  if (!playMem.isPlaying()) {
    playMem.play(drum_raw);
    delay(10);
  }
  */
}